#[test]
fn gate_iris_trustworthiness_matches_python() {
    let x = ndarray::Array2::from_shape_fn((150, 4), |(i, j)| IRIS_DATA[i][j]);
    let model = Umap::with_config(UmapConfig {
        n_neighbors: 10,
        min_dist: 0.1,
        n_components: 2,
        n_epochs: Some(50),
        random_state: Some(42),
        ..UmapConfig::default()
    })
    .fit(&x)
    .expect("fit");
    let t10 = trustworthiness(&x, &model.embedding, 10);
    assert!(
        (t10 - 0.9609814126394052).abs() < 0.02,
        "iris t10 {t10} vs python 0.9609814126394052"
    );
    assert!(model.embedding.iter().all(|v| v.is_finite()));
}

fn lcg_dataset(n: usize, d: usize, seed: u64) -> ndarray::Array2<f32> {
    let mut state = seed;
    let mut out = ndarray::Array2::<f32>::zeros((n, d));
    for i in 0..n {
        for j in 0..d {
            state = state
                .wrapping_mul(6364136223846793005)
                .wrapping_add(1442695040888963407);
            out[[i, j]] = ((state >> 11) as f64 / (1u64 << 53) as f64) as f32 * 2.0 - 1.0;
        }
    }
    for i in 0..n {
        let c = (i / (n / 4)) as f32;
        out[[i, 0]] += c * 8.0;
        out[[i, 1]] += c * 5.0;
    }
    out
}

#[test]
fn gate_digits_scale_trustworthiness_matches_python() {
    let x = lcg_dataset(1797, 10, 2024);
    let model = Umap::with_config(UmapConfig {
        n_neighbors: 15,
        min_dist: 0.1,
        n_components: 2,
        n_epochs: Some(50),
        random_state: Some(42),
        ..UmapConfig::default()
    })
    .fit(&x)
    .expect("fit");
    let t15 = trustworthiness(&x, &model.embedding, 15);
    assert!(
        (t15 - 0.9366227314847055).abs() < 0.02,
        "lcg1797 t15 {t15} vs python 0.9366227314847055"
    );
    assert!(model.embedding.iter().all(|v| v.is_finite()));
}

/// Python reference (repo baseline, `gen_phase7_large_ref.py`): trustworthiness
/// at `k = 15` of `UMAP(n_neighbors=15, min_dist=0.1, n_epochs=50,
/// random_state=42)` on the 5000-sample LCG dataset.
#[test]
fn gate_large_scale_lobpcg_trustworthiness_matches_python() {
    const PYTHON_T15: f64 = 0.925112391668341;
    let x = lcg_dataset(5000, 10, 2024);
    // Exact brute-force kNN (Rust has no approximate index; parity target is
    // statistical and Python's pynndescent kNN is near-exact at this scale).
    let metric = umap_rs::distances::named_distances("euclidean").expect("euclidean");
    let (knn_indices, knn_dists) = umap_rs::umap::brute_force_knn(&x, &x, 15, metric, &[]);
    let model = Umap::with_config(UmapConfig {
        n_neighbors: 15,
        min_dist: 0.1,
        n_components: 2,
        n_epochs: Some(50),
        random_state: Some(42),
        ..UmapConfig::default()
    })
    .fit_with_knn(Some(&x), &knn_indices, &knn_dists)
    .expect("fit");
    let t15 = trustworthiness(&x, &model.embedding, 15);
    assert!(
        (t15 - PYTHON_T15).abs() < 0.02,
        "lcg5000 t15 {t15} vs python {PYTHON_T15}"
    );
    assert!(model.embedding.iter().all(|v| v.is_finite()));
}
